/**
 * Thin, typed wrapper over Tauri IPC. Works (as a no-op) in a plain browser so
 * the UI can be developed and snapshot-tested without the Rust side.
 * Phase 2 replaces the hand-written types with ones generated by ts-rs.
 */
import type { Rect } from './geometry';

export interface BootConfig {
  /** Cycle expand/collapse automatically; used by the perf harness. */
  perfDemo: boolean;
}

const inTauri = typeof window !== 'undefined' && '__TAURI_INTERNALS__' in window;

async function call<T>(cmd: string, args?: Record<string, unknown>): Promise<T | undefined> {
  if (!inTauri) return undefined;
  const { invoke } = await import('@tauri-apps/api/core');
  return invoke<T>(cmd, args);
}

export async function bootConfig(): Promise<BootConfig> {
  return (await call<BootConfig>('boot_config')) ?? { perfDemo: false };
}

/** Tell the core which part of the window should receive mouse input. */
export function setHitRegion(rect: Rect): Promise<unknown> {
  return call('set_hit_region', { rect });
}

/** Signal that the first frame has been painted (cold-start measurement). */
export function uiReady(): Promise<unknown> {
  return call('ui_ready');
}
